# This test drives `Req.Test` through Plug; it is active only when
# `plug` is loaded. To run it, add `{:plug, "~> 1.0"}` to your deps
# — for all environments, not `only: :test`: `req` declares `plug`
# as an optional all-environment dependency, and a narrower scope
# diverges from it.
if Code.ensure_loaded?(Plug.Conn) do
  defmodule OhipDemo.Integrations.OhipTest do
    @moduledoc false

    # Generated by Hearth — verifies the auth scheme wired into
    # OhipDemo.Integrations.Ohip attaches credentials at request time.
    # The tests double as examples of every way to supply the credential.
    # Hearth-owned: regenerated on every `mix hearth.gen` run.

    use ExUnit.Case, async: false

    @client OhipDemo.Integrations.Ohip
    @api_key "hearth-test-credential"

    # Values Layer 1 takes per call, never from config.
    @opts [
      api_key: @api_key,
      hotel_id: "hearth-test-hotel_id",
      headers: [{"x-app-key", "hearth-test-x-app-key"}],
      base_url: "http://hearth.test"
    ]

    # Without `api_key:`, OhipDemo.Tenancy.token/1 resolves the credential —
    # it's yours to test.
    test "request! attaches a bearer token from the api_key: option" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == ["Bearer #{@api_key}"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} = @client.request!("/ping", @opts ++ [plug: plug])
    end

    test "a per-call api_key: may be a function" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == ["Bearer per-call-function"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, api_key: fn -> "per-call-function" end]
               )
    end

    test "a credential set explicitly on the request wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "authorization") == ["Bearer explicit-credential"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, auth: {:bearer, "explicit-credential"}]
               )
    end

    # Without the header on the request, OhipDemo.Tenancy.app_key/1 resolves
    # x-app-key — it's yours to test.
    test "an explicit x-app-key header wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "x-app-key") == ["explicit-credential"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, headers: [{"x-app-key", "explicit-credential"}]]
               )
    end

    test "request! sets the x-hotelid header from the hotel_id: option" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "x-hotelid") == ["hearth-test-hotel_id"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} = @client.request!("/ping", @opts ++ [plug: plug])
    end

    test "without hotel_id:, request! raises" do
      plug = fn conn -> Plug.Conn.send_resp(conn, 200, JSON.encode!(%{})) end

      assert_raise RuntimeError, ~r/missing :hotel_id/, fn ->
        @client.request!("/ping", Keyword.delete(@opts, :hotel_id) ++ [plug: plug])
      end
    end

    test "an explicit x-hotelid header wins" do
      plug = fn conn ->
        assert Plug.Conn.get_req_header(conn, "x-hotelid") == ["explicit-credential"]
        Plug.Conn.send_resp(conn, 200, JSON.encode!(%{}))
      end

      assert %Req.Response{status: 200} =
               @client.request!(
                 "/ping",
                 @opts ++ [plug: plug, headers: [{"x-hotelid", "explicit-credential"}]]
               )
    end
  end
end
